<?php
declare(strict_types=1);
function atomicFile(string $path,string $body):void{$tmp=$path.'.'.bin2hex(random_bytes(6)).'.tmp';if(file_put_contents($tmp,$body,LOCK_EX)===false||!rename($tmp,$path)){@unlink($tmp);throw new Fault('Não foi possível gravar a configuração atomicamente.',500);}@chmod($path,0600);}
function backupSnapshot():string{$tables=['tr_meta','tr_tenants','tr_users','tr_records','tr_contracts','tr_files','tr_audit','tr_login','tr_updates'];$data=['format'=>1,'version'=>APP_VERSION,'created'=>date(DATE_ATOM),'tables'=>[],'files'=>[]];$size=0;foreach($tables as $table){$data['tables'][$table]=query('SELECT * FROM '.$table)->fetchAll();$size+=strlen(j($data['tables'][$table]));if($size>33554432)throw new Fault('O banco excede o limite do backup interno. Faça um backup completo no cPanel antes de atualizar. Nenhuma alteração foi aplicada.',413);}foreach(glob(TR_PRIVATE.'/data/*.enc')?:[] as $file){$size+=filesize($file);if($size>67108864)throw new Fault('Os documentos excedem o limite do backup interno. Use o backup completo do cPanel. Nenhuma alteração foi aplicada.',413);$data['files'][basename($file)]=file_get_contents($file);}$name='backup-'.date('Ymd-His').'-'.uid().'.enc';atomicFile(TR_PRIVATE.'/backups/'.$name,seal(j($data)));return $name;}
function inspectUpdate(string $file):array{$zip=new ZipArchive();if($zip->open($file)!==true)throw new Fault('O arquivo não é um pacote ZIP válido.');try{if($zip->numFiles>10000)throw new Fault('Pacote com arquivos demais.');$raw=$zip->getFromName('manifest.json');$signature=$zip->getFromName('signature.b64');if($raw===false||strlen($raw)>1048576||$signature===false||openssl_verify($raw,base64_decode(trim($signature),true)?:'',file_get_contents(TR_PRIVATE.'/trusted-update-key.pem'),OPENSSL_ALGO_SHA256)!==1)throw new Fault('Assinatura do pacote inválida. Utilize um pacote oficial desta instalação.');$m=json_decode($raw,true,64,JSON_THROW_ON_ERROR);if(($m['app']??'')!=='trajetoria'||!preg_match('/^\d+\.\d+\.\d+$/',$m['version']??'')||!version_compare($m['version'],APP_VERSION,'>')||!version_compare(APP_VERSION,$m['min_from']??'9999.0.0','>=')||!version_compare(PHP_VERSION,$m['php']??'8.2.0','>='))throw new Fault('Versão incompatível ou já instalada.');if((int)(one('SELECT value FROM tr_meta WHERE id=?',['schema'])['value']??0)!==(int)$m['schema_from'])throw new Fault('O pacote não é compatível com a estrutura atual do banco.');$files=$m['files']??[];if(!$files||!isset($files['app/bootstrap.php'],$files['app/core.php'],$files['assets/workspace/index.html']))throw new Fault('Pacote incompleto.');$seen=[];$total=0;for($i=0;$i<$zip->numFiles;$i++){$stat=$zip->statIndex($i);$name=$stat['name'];if(in_array($name,['manifest.json','signature.b64'],true))continue;if(!str_starts_with($name,'release/'))throw new Fault('Há arquivo fora do diretório permitido.');$relative=substr($name,8);if(!preg_match('#^(app|assets|data|migrations)/[A-Za-z0-9_./-]+$#',$relative)||str_contains($relative,'..')||str_contains($relative,'\\')||!isset($files[$relative])||isset($seen[$relative]))throw new Fault('Caminho não permitido ou arquivo duplicado.');$zip->getExternalAttributesIndex($i,$opsys,$attrs);if((($attrs>>16)&0170000)===0120000)throw new Fault('Links simbólicos não são permitidos.');if($stat['size']!==$files[$relative]['size']||$stat['size']>16777216)throw new Fault('Tamanho de arquivo incompatível.');$total+=$stat['size'];if($total>83886080)throw new Fault('O pacote excede o tamanho permitido.');$stream=$zip->getStream($name);$ctx=hash_init('sha256');$read=hash_update_stream($ctx,$stream,16777217);fclose($stream);if($read!==$stat['size']||!hash_equals($files[$relative]['sha256'],hash_final($ctx)))throw new Fault('Arquivo do pacote corrompido.');$seen[$relative]=true;}if(count($seen)!==count($files))throw new Fault('Faltam arquivos declarados no manifesto.');return $m;}finally{$zip->close();}}
function maintenanceApi(array $u,string $action,string $method,array $b):array{platformOwner($u);
 if($action==='status'){$backups=[];foreach(glob(TR_PRIVATE.'/backups/*.enc')?:[] as $f)$backups[]=['name'=>basename($f),'size'=>filesize($f),'created'=>date(DATE_ATOM,filemtime($f))];$a=json_decode((string)file_get_contents(TR_PRIVATE.'/active.json'),true);return ['version'=>APP_VERSION,'schema'=>(int)(one('SELECT value FROM tr_meta WHERE id=?',['schema'])['value']??1),'previous'=>$a['previous']??null,'backups'=>$backups,'updates'=>query('SELECT * FROM tr_updates ORDER BY created DESC LIMIT 50')->fetchAll(),'maintenance'=>is_file(TR_PRIVATE.'/runtime/maintenance.json'),'demoEnabled'=>(bool)config()['demo_enabled']];}
 if($action==='backup-download'){$name=$_GET['name']??'';if(!preg_match('/^backup-[A-Za-z0-9-]+\.enc$/',$name)||!is_file(TR_PRIVATE.'/backups/'.$name))throw new Fault('Backup não encontrado.',404);header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="'.$name.'"');readfile(TR_PRIVATE.'/backups/'.$name);exit;}
 $input=$action==='upload'?$_POST:$b;if(!password_verify((string)($input['password']??''),$u['password_hash']))throw new Fault('Confirme sua senha atual para esta operação.',403);
 if($action==='backup')return ['name'=>backupSnapshot()];
 if($action==='demo'){if($method!=='POST'||!is_bool($b['enabled']??null))throw new Fault('Informe a situação das contas demonstrativas.');$cfg=config();$cfg['demo_enabled']=$b['enabled'];atomicFile(TR_PRIVATE.'/config.php',"<?php\ndeclare(strict_types=1);\nreturn ".var_export($cfg,true).";\n");if($b['enabled'])query('UPDATE tr_users SET demo_until=?,auth_epoch=auth_epoch+1 WHERE is_demo=1',[date('Y-m-d',strtotime('+30 days'))]);else query('UPDATE tr_users SET auth_epoch=auth_epoch+1 WHERE is_demo=1');return ['ok'=>true];}
 if($action==='upload'){$f=$_FILES['package']??null;if(!$f||$f['error']!==UPLOAD_ERR_OK||$f['size']>33554432||!is_uploaded_file($f['tmp_name']))throw new Fault('Envie um ZIP de atualização de até 32 MB.');return applyUpdate($f['tmp_name'],$u);}
 if($action==='rollback'){$a=json_decode((string)file_get_contents(TR_PRIVATE.'/active.json'),true);$previous=$a['previous']??'';if(!preg_match('/^\d+\.\d+\.\d+$/',$previous)||!is_file(TR_PRIVATE.'/releases/'.$previous.'/release-manifest.json'))throw new Fault('Não há versão anterior disponível.');$m=json_decode((string)file_get_contents(TR_PRIVATE.'/releases/'.$previous.'/release-manifest.json'),true);$schema=(int)(one('SELECT value FROM tr_meta WHERE id=?',['schema'])['value']??0);if($schema<($m['schema_min']??$m['schema_to'])||$schema>($m['schema_max']??$m['schema_to']))throw new Fault('A versão anterior não é compatível com o banco atual. Restaure o backup completo pelo procedimento documentado.');$backup=backupSnapshot();atomicFile(TR_PRIVATE.'/active.json',j(['version'=>$previous,'previous'=>APP_VERSION]));query('INSERT INTO tr_updates(id,from_version,to_version,status,created,actor,backup) VALUES(?,?,?,?,?,?,?)',[uid(),APP_VERSION,$previous,'Reversão do código',date(DATE_ATOM),$u['id'],$backup]);return ['ok'=>true,'version'=>$previous];}
 throw new Fault('Operação de manutenção não encontrada.',404);
}

function applyUpdate(string $file,array $u):array{platformOwner($u);$m=inspectUpdate($file);$id=uid();$backup=backupSnapshot();$stage=TR_PRIVATE.'/runtime/stage-'.$id;$target=TR_PRIVATE.'/releases/'.$m['version'];if(is_dir($target))throw new Fault('A versão já está no servidor. Use outro número de versão.');mkdir($stage,0700,true);$zip=new ZipArchive();$zip->open($file);try{foreach($m['files'] as $relative=>$meta){$out=$stage.'/'.$relative;if(!is_dir(dirname($out)))mkdir(dirname($out),0700,true);$in=$zip->getStream('release/'.$relative);$stream=fopen($out,'xb');stream_copy_to_stream($in,$stream,$meta['size']+1);fclose($in);fclose($stream);if(!hash_equals($meta['sha256'],hash_file('sha256',$out)))throw new Fault('Falha ao conferir o arquivo preparado.');chmod($out,0600);}atomicFile($stage.'/release-manifest.json',j($m));atomicFile(TR_PRIVATE.'/runtime/maintenance.json',j(['id'=>$id,'version'=>$m['version'],'backup'=>$backup]));foreach($m['migrations']??[] as $migration){if(!preg_match('#^migrations/\d{3}_[a-z0-9_]+\.php$#',$migration)||!isset($m['files'][$migration]))throw new Fault('Migração não declarada.');$old=one('SELECT value FROM tr_meta WHERE id=?',['migration:'.$migration]);if($old){if($old['value']!==$m['files'][$migration]['sha256'])throw new Fault('Migração aplicada foi modificada.');continue;}$run=require $stage.'/'.$migration;if(!is_callable($run))throw new Fault('Migração inválida.');$run(db());query('INSERT INTO tr_meta(id,value) VALUES(?,?)',['migration:'.$migration,$m['files'][$migration]['sha256']]);}query('UPDATE tr_meta SET value=? WHERE id=?',[(string)$m['schema_to'],'schema']);if(!rename($stage,$target))throw new Fault('Não foi possível ativar a pasta preparada.');atomicFile(TR_PRIVATE.'/active.json',j(['version'=>$m['version'],'previous'=>APP_VERSION]));query('INSERT INTO tr_updates(id,from_version,to_version,status,created,actor,backup) VALUES(?,?,?,?,?,?,?)',[$id,APP_VERSION,$m['version'],'Concluído',date(DATE_ATOM),$u['id'],$backup]);@unlink(TR_PRIVATE.'/runtime/maintenance.json');return ['ok'=>true,'version'=>$m['version'],'backup'=>$backup];}catch(Throwable $e){error_log('update_failure: '.$e->getMessage());throw new Fault('A atualização não foi concluída. A versão anterior e o backup foram preservados. Consulte o diagnóstico da instalação.',500);}finally{$zip->close();}}
